import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-Construction-Operator.md","filePath":"manual-en/Matrix-Construction-Operator.md","lastUpdated":1785684581000}'),n={name:"manual-en/Matrix-Construction-Operator.md"};function d(c,t,s,i,l,m){return a(),r("div",null,[...t[0]||(t[0]=[o('<h4 id="_16-4-1-1-matrix-construction-operator" tabindex="-1">16.4.1.1 Matrix Construction Operator <code>{}</code> <a class="header-anchor" href="#_16-4-1-1-matrix-construction-operator" aria-label="Permalink to &quot;16.4.1.1 Matrix Construction Operator `{}`&quot;">​</a></h4><p>Use the <code>{``}</code> operator to construct matrices. Within the curly braces, commas separate elements within a row and semicolons separate rows. The following examples show a <em>2×3</em> matrix, a <em>1×4</em> row vector, a <em>3×1</em> column vector, and a scalar.</p><table tabindex="0"><thead><tr><th>{1, 2, 3; 4, 5, 6}</th><th>⇒</th><th>[1 2 3] [4 5 6]</th></tr></thead><tbody><tr><td>{3.14, 6.28, 9.24, 12.57}</td><td>⇒</td><td>[3.14 6.28 9.42 12.57]</td></tr><tr><td>{1.41; 1.73; 2}</td><td>⇒</td><td>[1.41] [1.73] [2.00]</td></tr><tr><td>{5}</td><td>⇒</td><td>5</td></tr></tbody></table><p>Curly braces are not limited to holding numeric literals. They can contain calculations, and they can paste together matrices and vectors in any way as long as the result is rectangular. For example, if ‘m’ is matrix <code>{1, 2; 3, 4}</code>, ‘r’ is row vector <code>{5, 6}</code>, and ‘c’ is column vector <code>{7, 8}</code>, then curly braces can be used as follows:</p><table tabindex="0"><thead><tr><th>{m, c; r, 10}</th><th>⇒</th><th>[1 2 7] [3 4 8] [5 6 10]</th></tr></thead><tbody><tr><td>{c, 2 * c, T(r)}</td><td>⇒</td><td>[7 14 5] [8 16 6]</td></tr></tbody></table><p>The final example above uses the transposition function <code>T</code>.</p>',6)])])}const u=e(n,[["render",d]]);expor